/* From Uiverse.io by elijahgummer  - Tags: simple, animation, blue, switch, transition, click effect, click animation */
.__UIV_SCOPE__ .checkbox {
  --blue: #0d7eff;
  --g08: #e1e5eb;
  --g04: #848ea1;
  text-align: center;
}

.__UIV_SCOPE__ .checkbox .tgl {
  display: none;
}
.__UIV_SCOPE__ .checkbox .tgl,
.__UIV_SCOPE__ .checkbox .tgl:after,
.__UIV_SCOPE__ .checkbox .tgl:before,
.__UIV_SCOPE__ .checkbox .tgl *,
.__UIV_SCOPE__ .checkbox .tgl *:after,
.__UIV_SCOPE__ .checkbox .tgl *:before,
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn {
  box-sizing: border-box;
}
.__UIV_SCOPE__ .checkbox .tgl::selection,
.__UIV_SCOPE__ .checkbox .tgl:after::selection,
.__UIV_SCOPE__ .checkbox .tgl:before::selection,
.__UIV_SCOPE__ .checkbox .tgl *::selection,
.__UIV_SCOPE__ .checkbox .tgl *:after::selection,
.__UIV_SCOPE__ .checkbox .tgl *:before::selection,
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn::selection {
  background: none;
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn {
  outline: 0;
  display: block;
  width: 57px;
  height: 27px;
  position: relative;
  cursor: pointer;
  user-select: none;
  font-size: 12px;
  font-weight: 400;
  color: #fff;
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:after,
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:before {
  position: relative;
  display: block;
  content: "";
  width: 44%;
  height: 100%;
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:after {
  left: 0;
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:before {
  display: inline;
  position: absolute;
  top: 7px;
}
.__UIV_SCOPE__ .checkbox .tgl:checked + .tgl-btn:after {
  left: 56.5%;
}

.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn {
  background: var(--g08);
  border-radius: 20rem;
  padding: 2px;
  transition: all 0.4s ease;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.1);
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:after {
  border-radius: 2em;
  background: #fff;
  transition: left 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275),
    padding 0.3s ease, margin 0.3s ease;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.2);
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:before {
  content: "No";
  left: 28px;
  color: var(--g04);
  transition: left 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:active {
  box-shadow: inset 0 0 0 30px rgba(0, 0, 0, 0.1);
}
.__UIV_SCOPE__ .checkbox .tgl + .tgl-btn:active:after {
  padding-right: 0.4em;
}
.__UIV_SCOPE__ .checkbox .tgl:checked + .tgl-btn {
  background: var(--blue);
}
.__UIV_SCOPE__ .checkbox .tgl:checked + .tgl-btn:active {
  box-shadow: inset 0 0 0 30px rgba(0, 0, 0, 0.1);
}
.__UIV_SCOPE__ .checkbox .tgl:checked + .tgl-btn:active:after {
  margin-left: -0.4em;
}
.__UIV_SCOPE__ .checkbox .tgl:checked + .tgl-btn:before {
  content: "Yes";
  left: 4px;
  color: #fff;
}
